function draw(){graphData=buildGraph();transmissionLabelRects=[];refreshHighlight();const svg=$('graph');svg.replaceChildren();$('emptyGraph').classList.toggle('hidden',graphData.nodes.length>0);if(!graphData.nodes.length){svg.removeAttribute('viewBox');renderReadingSections();return;}let minX=0,maxX=graphData.width,minY=0,maxY=graphData.height;graphData.nodes.forEach(node=>{minX=Math.min(minX,node.x-node.w/2-8);maxX=Math.max(maxX,node.x+node.w/2+8);minY=Math.min(minY,node.y-node.h/2-8);maxY=Math.max(maxY,node.y+node.h/2+8);});const padding=50,width=maxX-minX+padding*2,height=maxY-minY+padding*2;svg.setAttribute('viewBox',`${minX-padding} ${minY-padding} ${width} ${height}`);svg.setAttribute('width',width);svg.setAttribute('height',height);svg.append(textEl('rect',{class:'export-background',x:minX-padding,y:minY-padding,width,height,fill:'#fcfdfb'}));if(graphData.matnLines.length){const group=textEl('g',{class:'matn-layer'});appendSvgLines(group,graphData.matnLines,{x:(minX+maxX)/2,y:32,'text-anchor':'middle','font-size':24,'font-weight':700,fill:'#263e35',direction:'rtl'},30);group.append(textEl('line',{x1:(minX+maxX)/2-170,x2:(minX+maxX)/2+170,y1:graphData.matnHeight-18,y2:graphData.matnHeight-18,stroke:'#d7c28f'}));svg.append(group);}const layer=textEl('g',{class:'diagram-layer'}),byId=new Map(graphData.nodes.map(node=>[node.id,node]));for(const edge of graphData.edges){const from=byId.get(edge.from),to=byId.get(edge.to),storageId=edgeStorageId(edge),d=edgePath(from,to),colors=edgeColors(edge);colors.forEach((color,index)=>{const classes=['edge'];if(highlightedRouteIds.size)classes.push(edge.paths.some(path=>highlightedRouteIds.has(project.chains[path].id))?'route-focus':'route-dim');layer.append(textEl('path',{class:classes.join(' '),'data-edge-id':edge.id,d,stroke:color,'stroke-width':colors.length>1?3:4,transform:colors.length>1?`translate(${(index-(colors.length-1)/2)*5} 0)`:''}));});const hit=textEl('path',{class:'edge-hit','data-id':edge.id,d,tabindex:0,role:'button','aria-label':`وصلة ${graphNodeName(from)} إلى ${graphNodeName(to)}`});hit.addEventListener('click',event=>{event.stopPropagation();showEdge(edge.id);});hit.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();showEdge(edge.id);}});layer.append(hit);appendTransmissionLabels(layer,edge,from,to);if(project.edges[storageId]?.note){const middle=curveMid(from,to);layer.append(textEl('circle',{cx:middle.x,cy:middle.y,r:9,class:'footnote-badge'}));layer.append(textEl('text',{x:middle.x,y:middle.y+4,'text-anchor':'middle','font-size':10,fill:'#fff'},footnoteNumber('edge',storageId)));}}graphData.nodes.forEach(node=>appendNode(layer,node));svg.append(layer);applyZoom();renderReadingSections();}

function updateSelection(){document.querySelectorAll('#graph .selected').forEach(element=>element.classList.remove('selected'));if(selected?.type==='node')document.querySelector(`#graph .node[data-id="${CSS.escape(selected.id)}"]`)?.classList.add('selected');}
function showNode(id){const node=graphData.nodes.find(item=>graphIdentityId(item)===id&&!item.isSourceAppearance)||graphData.nodes.find(item=>graphIdentityId(item)===id);if(!node)return;selected={type:'node',id};const meta=nodeMeta(id,node.name),routeIndexes=project.chains.map((chain,index)=>chain.narrators.some(item=>item.identityId===id)?index:-1).filter(index=>index>=0),compilers=[...new Set(routeIndexes.map(index=>compilerName(project.chains[index])).filter(Boolean))];$('inspector').innerHTML=`<h2>${escapeHtml(meta.name||node.name)}</h2><p class="muted">يمر بهذا الراوي ${arabicDigits(routeIndexes.length)} من أصل ${arabicDigits(project.chains.length)} طريقًا مسجلًا${compilers.length?`، وتنتهي إلى: ${escapeHtml(compilers.join('، '))}`:''}.</p>${meta.note?`<div class="info-list"><div class="info-line"><strong>ملاحظة الراوي</strong><br>${escapeHtml(meta.note)}</div></div>`:''}<div class="inspector-actions"><button id="toggleNodeRoutes" class="button secondary" type="button">${highlightedNarratorId===id?'إلغاء تمييز طرق الراوي':'تمييز جميع طرق الراوي'}</button></div>`;$('toggleNodeRoutes').onclick=()=>{highlightedNarratorId=highlightedNarratorId===id?null:id;highlightedChainId=null;draw();showNode(id);};updateSelection();}
function showEndpoint(node,indexes){selected={type:'node',id:node.id};$('inspector').innerHTML=`<h2>${escapeHtml(nodeName(node.id,node.name))}</h2><p class="muted">تنتهي إلى هذه العقدة عدة طرق منشورة. اختر طريقًا لتمييزه.</p><div class="inspector-actions">${indexes.map(index=>`<button class="button secondary" data-chain="${escapeHtml(project.chains[index].id)}">${escapeHtml(routeDisplayLabel(project.chains[index],index))}</button>`).join('')}</div>`;$('inspector').querySelectorAll('[data-chain]').forEach(button=>button.onclick=()=>highlightChain(button.dataset.chain));updateSelection();}
function showEdge(id){const edge=graphData.edges.find(item=>item.id===id);if(!edge)return;selected={type:'edge',id};const meta=project.edges[edgeStorageId(edge)]||{},segments=edge.segments.filter(segment=>segment.wording);$('inspector').innerHTML=`<h2>${escapeHtml(nodeName(edge.fromIdentityId||edge.from))} ← ${escapeHtml(nodeName(edge.toIdentityId||edge.to))}</h2>${segments.length?`<div class="info-list">${segments.map(segment=>`<div class="info-line"><strong>${escapeHtml(routeDisplayLabel(project.chains[segment.chainIndex],segment.chainIndex))}</strong><br>صيغة الأداء: ${escapeHtml(segment.wording)}</div>`).join('')}</div>`:'<p class="muted">لا توجد صيغة أداء منشورة لهذه الوصلة.</p>'}${meta.note?`<div class="info-line"><strong>ملاحظة الوصلة</strong><br>${escapeHtml(meta.note)}</div>`:''}`;updateSelection();}
function highlightChain(id){activeObservationId=null;highlightedNarratorId=null;highlightedChainId=highlightedChainId===id?null:id;draw();}
function activateNarrator(id){activeObservationId=null;highlightedChainId=null;highlightedNarratorId=id;draw();showNode(id);}
function clearHighlight(){highlightedNarratorId=null;highlightedChainId=null;activeObservationId=null;highlightedRouteIds=new Set();selected=null;draw();$('inspector').innerHTML='<h2>تفاصيل العنصر</h2><p class="muted">انقر على راوٍ أو وصلة لقراءة المعلومات المنشورة وتمييز الطرق المرتبطة به.</p>';}
function summaryLines(){const identityRoutes=new Map(),outgoing=new Map();project.chains.forEach((chain,index)=>{const seen=new Set();for(const narrator of chain.narrators)if(!seen.has(narrator.identityId)){seen.add(narrator.identityId);if(!identityRoutes.has(narrator.identityId))identityRoutes.set(narrator.identityId,new Set());identityRoutes.get(narrator.identityId).add(index);}for(let position=1;position<chain.narrators.length;position++){const from=chain.narrators[position-1].identityId,to=chain.narrators[position].identityId;if(!outgoing.has(from))outgoing.set(from,new Set());outgoing.get(from).add(to);}});const candidates=[...outgoing].filter(([id,targets])=>targets.size>1&&(identityRoutes.get(id)?.size||0)>1&&!nodeMeta(id).isCompiler&&!isProphetName(nodeName(id))).map(([id,targets])=>({name:nodeName(id),count:identityRoutes.get(id).size,branches:targets.size})).sort((a,b)=>b.count-a.count||b.branches-a.branches||a.name.localeCompare(b.name,'ar')),strongest=candidates.length?candidates.filter(item=>item.count===candidates[0].count).slice(0,4):[];const lines=[`الطرق المسجلة: ${arabicDigits(project.chains.length)}`,`هويات الرواة والمصنفين: ${arabicDigits(identityRoutes.size)}`];if(strongest.length===1)lines.push(`موضع تفرّع الطرق المسجلة: ${strongest[0].name}`);else if(strongest.length>1)lines.push(`مواضع تفرّع بارزة: ${strongest.map(item=>item.name).join('، ')}`);else lines.push('لا يظهر موضع تفرّع مميّز في الطرق المسجلة.');return lines;}
function renderObservations(){const panel=$('researchObservations'),list=$('researchObservationsList'),observations=project.routeObservations||[];panel.classList.toggle('hidden',!observations.length);if(!observations.length){list.replaceChildren();return;}list.innerHTML=observations.map(observation=>{const type=observationType(observation.presentationType),result=observationResult(observation),active=activeObservationId===observation.id,label=type==='selective'?'إبراز رواة معينين':(observationMode(observation.mode)==='comparison'?'تلخيص بالمقارنة':'تلخيص بالاشتراك');return`<details class="public-observation" ${active?'open':''} data-id="${escapeHtml(observation.id)}"><summary><span><strong>${escapeHtml(observation.title)}</strong><small>${label} • ${arabicDigits(result.matches.length)} طرق فريدة</small></span><button type="button" class="button secondary" data-activate aria-pressed="${active}">${active?'إلغاء التضمين والتمييز':'تضمين في التصدير وتمييز'}</button></summary><div class="public-observation-body">${observation.comment?`<p class="researcher-comment"><strong>تعليق الباحث:</strong> ${escapeHtml(observation.comment)}</p>`:''}<p><strong>الرواة:</strong> ${escapeHtml(observation.narratorIds.map(observationNarratorName).join('، '))}</p>${type==='selective'?`<p><strong>الراوي المشترك:</strong> ${escapeHtml(observationNarratorName(observation.sharedNarratorId))}</p>`:''}${observationCompactHtml(observation)}</div></details>`;}).join('');list.querySelectorAll('.public-observation').forEach(card=>card.querySelector('[data-activate]').onclick=event=>{event.preventDefault();event.stopPropagation();activeObservationId=activeObservationId===card.dataset.id?null:card.dataset.id;highlightedNarratorId=null;highlightedChainId=null;draw();});}
function renderReadingSections(){$('structureSummary').innerHTML=summaryLines().map(line=>`<div class="summary-stat">${escapeHtml(line)}</div>`).join('');$('routeCount').textContent=`(${arabicDigits(project.chains.length)})`;$('routesList').innerHTML=project.chains.map((chain,index)=>{const wording=chain.transmissions.map((value,segmentIndex)=>value?`${chain.narrators[segmentIndex].name} ← ${chain.narrators[segmentIndex+1].name}: ${value}`:'').filter(Boolean);return`<li class="route-item"><div class="route-title-row"><strong class="route-title"><i class="role-key-swatch" style="display:inline-block;vertical-align:middle;background:${chainIndicator(chain,index)};border-color:${chainIndicator(chain,index)}"></i> ${escapeHtml(routeDisplayLabel(chain,index))}</strong><button type="button" class="button secondary" data-highlight-chain="${escapeHtml(chain.id)}">${highlightedChainId===chain.id?'إلغاء التمييز':'تمييز الطريق'}</button></div><p class="route-path">${escapeHtml(chainDisplayNarrators(chain).map(item=>item.name).join(' ← '))}</p>${sourceText(chain)?`<p class="route-extra">المصدر: ${escapeHtml(sourceText(chain))}</p>`:''}${wording.length?`<p class="route-extra">صيغ الأداء: ${escapeHtml(wording.join('؛ '))}</p>`:''}${chain.note?`<p class="route-extra">ملاحظة الطريق: ${escapeHtml(chain.note)}</p>`:''}</li>`;}).join('')||'<li class="empty">لا توجد طرق مسجلة.</li>';$('routesList').querySelectorAll('[data-highlight-chain]').forEach(button=>button.onclick=()=>highlightChain(button.dataset.highlightChain));const items=footnoteItems().map(note=>({label:note.label,text:note.text}));if(project.researchNotes)items.push({label:'ملاحظات الباحث',text:project.researchNotes});$('notesCount').textContent=`(${arabicDigits(items.length)})`;$('notesList').innerHTML=items.map((item,index)=>`<div class="note-entry"><b class="note-num">${arabicDigits(index+1)}</b><div><strong>${escapeHtml(item.label)}:</strong><br>${escapeHtml(item.text)}</div></div>`).join('')||'<p class="muted">لا توجد مراجع أو ملاحظات منشورة.</p>';$('clearHighlight').classList.toggle('hidden',!highlightedRouteIds.size);renderRouteKey();renderRoleKey();renderObservations();}
function renderRouteKey(){const panel=$('routeLegend'),root=$('routeKey');panel.classList.toggle('hidden',!project.settings.showLegend);if(!project.settings.showLegend){root.replaceChildren();return;}$('routeLegendCount').textContent=`(${arabicDigits(project.chains.length)})`;root.innerHTML=project.chains.map((chain,index)=>`<button type="button" class="role-key-item" data-route-key="${escapeHtml(chain.id)}" aria-pressed="${highlightedChainId===chain.id}"><i class="role-key-swatch" style="background:${chainIndicator(chain,index)};border-color:${chainIndicator(chain,index)}"></i>${escapeHtml(routeDisplayLabel(chain,index))}</button>`).join('');root.querySelectorAll('[data-route-key]').forEach(button=>button.onclick=()=>highlightChain(button.dataset.routeKey));}
