function applyZoom(){const svg=$('graph'),width=Number(svg.getAttribute('width'))||0,height=Number(svg.getAttribute('height'))||0;svg.style.width=width?`${width*zoom}px`:'';svg.style.height=height?`${height*zoom}px`:'';$('zoomReset').textContent=`${arabicDigits(Math.round(zoom*100))}٪`;}
function centerViewport(behavior='auto'){const viewport=$('diagramViewport'),svg=$('graph');requestAnimationFrame(()=>viewport.scrollTo({top:0,left:Math.max(0,(svg.getBoundingClientRect().width-viewport.clientWidth)/2),behavior}));}
function fitDiagram(){const svg=$('graph'),viewport=$('diagramViewport');if(!svg.viewBox.baseVal.width)return;zoom=Math.max(.2,Math.min(1.2,(viewport.clientWidth-30)/svg.viewBox.baseVal.width,(viewport.clientHeight-30)/svg.viewBox.baseVal.height));applyZoom();centerViewport('smooth');}
function bindPan(){const viewport=$('diagramViewport');let active=false,startX=0,startY=0,left=0,top=0,moved=false;viewport.addEventListener('pointerdown',event=>{if(event.button!==0||event.target.closest('.node,.edge-hit,button'))return;active=true;moved=false;startX=event.clientX;startY=event.clientY;left=viewport.scrollLeft;top=viewport.scrollTop;viewport.classList.add('dragging');viewport.setPointerCapture(event.pointerId);});viewport.addEventListener('pointermove',event=>{if(!active)return;const dx=event.clientX-startX,dy=event.clientY-startY;if(Math.abs(dx)+Math.abs(dy)>4)moved=true;viewport.scrollLeft=left-dx;viewport.scrollTop=top-dy;});const stop=()=>{active=false;viewport.classList.remove('dragging');};viewport.addEventListener('pointerup',event=>{if(active&&!moved)clearHighlight();stop();});viewport.addEventListener('pointercancel',stop);viewport.addEventListener('lostpointercapture',stop);}

function download(name,blob){const url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=name;document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),2500);}
function safeFile(extension){return(project.title||'مشجر-الأسانيد').replace(/[\\/:*?"<>|]/g,'-')+`.${extension}`;}
async function waitForAmiri(){if(!document.fonts)return;await document.fonts.load('19px Amiri','العربية ﷺ');await document.fonts.ready;}
function bufferToBase64(buffer){const bytes=new Uint8Array(buffer);let binary='';for(let offset=0;offset<bytes.length;offset+=8192)binary+=String.fromCharCode(...bytes.subarray(offset,offset+8192));return btoa(binary);}
async function fontDataUrl(path){const response=await fetch(path);if(!response.ok)throw Error('تعذّر تحميل خط Amiri المحلي للتصدير.');return`data:font/woff2;base64,${bufferToBase64(await response.arrayBuffer())}`;}
function embeddedExportFontCss(){return exportFontCssPromise||=(async()=>{const [a400,l400,a700,l700]=await Promise.all(['assets/amiri-arabic-400.woff2','assets/amiri-latin-400.woff2','assets/amiri-arabic-700.woff2','assets/amiri-latin-700.woff2'].map(fontDataUrl));return`@font-face{font-family:'Amiri Embedded';font-weight:400;src:url('${a400}') format('woff2');unicode-range:U+0600-06FF,U+0750-077F,U+0870-089F,U+08A0-08FF,U+FB50-FDFF,U+FE70-FEFC,U+1EE00-1EEFF}@font-face{font-family:'Amiri Embedded';font-weight:400;src:url('${l400}') format('woff2')}@font-face{font-family:'Amiri Embedded';font-weight:700;src:url('${a700}') format('woff2');unicode-range:U+0600-06FF,U+0750-077F,U+0870-089F,U+08A0-08FF,U+FB50-FDFF,U+FE70-FEFC,U+1EE00-1EEFF}@font-face{font-family:'Amiri Embedded';font-weight:700;src:url('${l700}') format('woff2')}`;})();}
async function createExportSvg(){const base=$('graph').cloneNode(true),viewBox=$('graph').viewBox.baseVal,original={x:viewBox.x,y:viewBox.y,width:viewBox.width,height:viewBox.height},observation=activeObservation(),contentWidth=original.width-56;base.querySelectorAll('.edge-hit').forEach(element=>element.remove());base.querySelectorAll('.selected,.route-origin').forEach(element=>element.classList.remove('selected','route-origin'));if(!observation)base.querySelectorAll('.route-focus,.route-dim').forEach(element=>element.classList.remove('route-focus','route-dim'));const blocks=[];if(observation)observationExportLines(observation).forEach((line,index)=>blocks.push({lines:wrapSvgText(line,contentWidth,'17px Amiri,serif'),bold:index===0}));const chainNoteUnits=project.chains.map((chain,index)=>chain.note?`${routeDisplayLabel(chain,index).replace(' ',' ')}: ${chain.note}`:'').filter(Boolean);if(chainNoteUnits.length)blocks.push({label:'ملاحظات الطرق',lines:packNoteUnits(chainNoteUnits,contentWidth,'17px Amiri,serif')});footnoteItems().forEach(note=>blocks.push({lines:wrapSvgText(`${note.label}: ${note.text}`,contentWidth,'17px Amiri,serif')}));if(project.researchNotes)blocks.push({lines:wrapSvgText(`ملاحظات الباحث: ${project.researchNotes}`,contentWidth,'17px Amiri,serif')});const topLines=[project.title,project.researcher&&`دراسة وإعداد: ${project.researcher}`].filter(Boolean),topHeight=topLines.length*34+28,footerHeight=blocks.reduce((sum,block)=>sum+Math.max(1,block.lines.length)*27+10,0)+(blocks.length?62:20),newY=original.y-topHeight,newHeight=original.height+topHeight+footerHeight;base.setAttribute('viewBox',`${original.x} ${newY} ${original.width} ${newHeight}`);base.setAttribute('width',original.width);base.setAttribute('height',newHeight);const bg=base.querySelector('.export-background');if(bg){bg.setAttribute('y',newY);bg.setAttribute('height',newHeight);}let y=newY+30;topLines.forEach((line,index)=>{base.append(textEl('text',{x:original.x+original.width/2,y,'text-anchor':'middle','font-size':index?17:30,'font-weight':index?400:700,fill:index?'#66776f':'#173c31',direction:'rtl'},line));y+=34;});let footerY=original.y+original.height+30;if(blocks.length){base.append(textEl('line',{x1:original.x+24,x2:original.x+original.width-24,y1:footerY-12,y2:footerY-12,stroke:'#dfe7e2'}));base.append(textEl('text',{x:original.x+original.width-28,y:footerY+10,'text-anchor':'start','font-size':20,'font-weight':700,fill:'#173c31',direction:'rtl'},observation?'الملاحظة البحثية والملاحظات':'المراجع والملاحظات'));footerY+=45;}blocks.forEach(block=>{if(block.label){base.append(textEl('text',{x:original.x+original.width-28,y:footerY,'text-anchor':'start','font-size':17,'font-weight':700,fill:'#173c31',direction:'rtl'},block.label));footerY+=27;}appendSvgLines(base,block.lines,{x:original.x+original.width-28,y:footerY,'text-anchor':'start','font-size':17,'font-weight':block.bold?700:400,fill:'#33463f',direction:'rtl'},27);footerY+=Math.max(1,block.lines.length)*27+10;});const style=textEl('style',{},`${await embeddedExportFontCss()}text{font-family:"Amiri Embedded",Amiri,serif;unicode-bidi:plaintext}.edge{fill:none;stroke-linecap:round}.route-dim{opacity:.13}.route-focus{opacity:1}.node.route-focus rect{stroke:#d49b42;stroke-width:3}`);base.insertBefore(style,base.firstChild);base.setAttribute('xmlns',NS);return new XMLSerializer().serializeToString(base);}
const createExportSvgContent=createExportSvg;
createExportSvg=async function(){const source=await createExportSvgContent(),documentRoot=new DOMParser().parseFromString(source,'image/svg+xml').documentElement,viewBox=documentRoot.getAttribute('viewBox').split(/\s+/).map(Number),padding=32;viewBox[3]+=padding;documentRoot.setAttribute('viewBox',viewBox.join(' '));documentRoot.setAttribute('height',viewBox[3]);const background=documentRoot.querySelector('.export-background');if(background)background.setAttribute('height',Number(background.getAttribute('height')||0)+padding);return new XMLSerializer().serializeToString(documentRoot);};
async function exportSvg(){try{await waitForAmiri();download(safeFile('svg'),new Blob([await createExportSvg()],{type:'image/svg+xml;charset=utf-8'}));}catch(error){toast(error.message);}}
async function exportPng(){try{await waitForAmiri();const source=await createExportSvg(),url=URL.createObjectURL(new Blob([source],{type:'image/svg+xml;charset=utf-8'})),image=new Image();image.onload=()=>{const ratio=image.naturalWidth/image.naturalHeight,canvas=document.createElement('canvas');canvas.width=Math.min(12000,Math.max(1800,image.naturalWidth*3));canvas.height=Math.round(canvas.width/ratio);const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>blob?download(safeFile('png'),blob):toast('تعذّر إنشاء PNG.'),'image/png');URL.revokeObjectURL(url);};image.onerror=()=>{URL.revokeObjectURL(url);toast('تعذّر إنشاء PNG؛ جرّب SVG.');};image.src=url;}catch(error){toast(error.message);}}
function openReport(){try{localStorage.setItem('hadithTreePrintReport',JSON.stringify({project,observation:activeObservation(),createdAt:new Date().toISOString()}));const report=window.open('report.html','_blank');if(!report)throw Error('منع المتصفح فتح نافذة التقرير. اسمح بالنوافذ المنبثقة ثم أعد المحاولة.');report.opener=null;}catch(error){toast(error.message);}}

function bind(){
  if(matchMedia('(max-width:780px)').matches)$('routeLegend').removeAttribute('open');
  $('zoomIn').onclick=()=>{zoom=Math.min(2.5,zoom+.15);applyZoom();};
  $('zoomOut').onclick=()=>{zoom=Math.max(.2,zoom-.15);applyZoom();};
  $('zoomReset').onclick=()=>{zoom=1;applyZoom();centerViewport();};
  $('fitDiagram').onclick=fitDiagram;$('clearHighlight').onclick=clearHighlight;
  $('exportSvg').onclick=exportSvg;$('exportPng').onclick=exportPng;$('exportPdf').onclick=openReport;
  $('graph').addEventListener('click',event=>{if(!event.target.closest('.node,.edge-hit'))clearHighlight();});
  bindPan();window.addEventListener('resize',()=>{if(project)fitDiagram();},{passive:true});
}

async function load(){
  try{
    const id=new URLSearchParams(location.search).get('project');
    if(!id||!/^[a-z0-9][a-z0-9_-]*$/i.test(id))throw Error('لم يُحدّد مشجّر صالح. ارجع إلى المكتبة واختر مشروعًا منشورًا.');
    const indexResponse=await fetch('data/index.json',{cache:'no-store'});if(!indexResponse.ok)throw Error(`تعذّر تحميل فهرس المكتبة (${indexResponse.status}).`);
    const indexData=await indexResponse.json(),entries=Array.isArray(indexData)?indexData:indexData.projects;
    if(!Array.isArray(entries))throw Error('بنية فهرس المكتبة غير صالحة.');
    const entry=entries.find(item=>item?.id===id);if(!entry)throw Error('المشجّر المطلوب غير موجود في فهرس المكتبة.');
    if(typeof entry.file!=='string'||entry.file.includes('..')||/^(?:[a-z]+:|\/)/i.test(entry.file))throw Error('مسار ملف المشروع غير صالح.');
    const response=await fetch(`data/${entry.file.replace(/^data\//,'')}`,{cache:'no-store'});if(!response.ok)throw Error(`تعذّر تحميل ملف المشروع المنشور (${response.status}).`);
    const text=await response.text();if(new Blob([text]).size>LIMITS.file)throw Error('حجم ملف المشروع يتجاوز الحد الآمن للعرض.');
    project=normalizeProject(JSON.parse(text));assertAcyclic();
    document.title=`${project.title||entry.title} · مشجّرات الأسانيد`;$('projectTitle').textContent=project.title||entry.title;$('researcher').textContent=project.researcher?`دراسة وإعداد: ${project.researcher}`:'';$('researcher').classList.toggle('hidden',!project.researcher);const savedDate=new Date(project.updatedAt),validDate=project.updatedAt&&!Number.isNaN(savedDate.getTime()),status=project.researchStatus==='complete'?'مكتمل':'قيد البحث';$('projectMeta').textContent=`حالة البحث: ${status}${validDate?` • آخر تعديل: ${savedDate.toLocaleDateString('ar-EG',{dateStyle:'medium'})}`:''}`;
    $('loading').classList.add('hidden');$('viewerContent').classList.remove('hidden');draw();fitDiagram();
  }catch(error){$('loading').classList.add('hidden');const target=$('viewerError');target.textContent=error instanceof SyntaxError?'ملف المشروع المنشور ليس JSON صالحًا.':error.message;target.classList.remove('hidden');console.warn(error);}
}

bind();load();
